const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const aoi = ee.Geometry.Point([7.578886, 38.602260]).buffer(30000);
  const year = 2022;
  const minAreaKm2 = 25;

  // 2. Data Acquisition & Check
  // JRC Global Surface Water dataset provides annual water classifications.
  const jrcCollection = ee.ImageCollection('JRC/GSW1_4/YearlyHistory')
    .filterDate(`${year}-01-01`, `${year}-12-31`);

  const imageCount = jrcCollection.size().getInfo();
  if (imageCount === 0) {
    console.log(`Evidence: No JRC water data found for the year ${year}.`);
    console.log("C1");
    return;
  }
  const jrcImage = jrcCollection.first();

  // 3. Processing: Create a water mask
  // The 'waterClass' band values: 2=seasonal, 3=permanent. We want both.
  const waterMask = jrcImage.select('waterClass').gte(2).selfMask();

  const totalWaterPixels = waterMask.reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: aoi,
    scale: 30,
    maxPixels: 1e9
  }).get('waterClass').getInfo();

  if (totalWaterPixels === 0) {
    console.log(`Evidence: No water pixels found in the AOI for ${year}.`);
    console.log("C2");
    return;
  }

  // 4. Calculation: Convert raster water bodies to vectors and filter by size
  // Calculate the area of each pixel to sum up later.
  const areaImage = ee.Image.pixelArea().addBands(waterMask);

  // Define a reducer that sums the area of connected components.
  const areaReducer = ee.Reducer.sum().group({
    groupField: 1,
    groupName: 'label',
  });

  // Identify connected components (individual lakes).
  const connectedComponents = waterMask.connectedComponents({
    connectedness: ee.Kernel.plus(1),
    maxSize: 1024
  });

  // Calculate the area of each component (lake).
  const lakeAreas = areaImage.reduceRegion({
    reducer: areaReducer,
    geometry: aoi,
    scale: 30,
    maxPixels: 1e10
  });

  const groups = ee.List(lakeAreas.get('groups'));

  // Function to filter lakes by the minimum area requirement.
  const filterLakes = (group) => {
    const dict = ee.Dictionary(group);
    const area = ee.Number(dict.get('sum')); // Area in square meters
    return area.gte(minAreaKm2 * 1e6); // Convert km^2 to m^2
  };

  const largeLakes = groups.filter(filterLakes);
  const largeLakeCount = largeLakes.size().getInfo();

  // 5. Validation & Final Answer
  if (largeLakeCount === null || isNaN(largeLakeCount)) {
    console.log("Evidence: Failed to calculate the number of large lakes.");
    console.log("C3");
    return;
  }

  console.log(`Evidence: Found JRC image for ${year}.`);
  console.log(`Evidence: Total water pixels detected: ${totalWaterPixels}.`);
  console.log(`Evidence: Number of distinct water bodies (lakes) found: ${groups.size().getInfo()}.`);
  console.log(`Evidence: Number of lakes larger than ${minAreaKm2} km²: ${largeLakeCount}.`);

  if (largeLakeCount > 2) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  try {
    await new Promise((resolve, reject) => {
      ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
    });
    await new Promise((resolve, reject) => {
      ee.initialize(null, null, resolve, reject);
    });
    await runAnalysis();
  } catch (e) {
    console.error(`Error during Earth Engine initialization or analysis: ${e}`);
    console.log("D");
  }
}

initEE();
